package com.waypoint.planning.integration;

import com.fasterxml.jackson.databind.*;import com.waypoint.planning.messaging.PlanningEventPublisher;import jakarta.persistence.EntityManager;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.mock.mockito.MockBean;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.context.DynamicPropertyRegistry;import org.springframework.test.context.DynamicPropertySource;import org.springframework.test.web.servlet.MockMvc;import org.springframework.test.web.servlet.request.RequestPostProcessor;import org.testcontainers.containers.PostgreSQLContainer;import org.testcontainers.junit.jupiter.*;
import java.nio.file.Files;import java.nio.file.Path;import java.io.IOException;import java.sql.*;import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

@Testcontainers(disabledWithoutDocker=true)
@org.springframework.test.context.ActiveProfiles("test")
@SpringBootTest(properties={"grpc.server.port=-1","waypoint.planning.master-data.mode=jdbc"})
@AutoConfigureMockMvc
class PlanningPostgresIntegrationTest {
 private static final String TEST_USER_ID="00000000-0000-0000-0000-000000000001";
 @Container static final PostgreSQLContainer<?> postgres=new PostgreSQLContainer<>("postgres:16-alpine").withDatabaseName("waypoint").withUsername("waypoint").withPassword("waypoint");
 @DynamicPropertySource static void database(DynamicPropertyRegistry registry)throws Exception{postgres.start();try(Connection connection=DriverManager.getConnection(postgres.getJdbcUrl(),postgres.getUsername(),postgres.getPassword())){try(Statement statement=connection.createStatement()){statement.execute("CREATE SCHEMA auth; CREATE TABLE auth.users(id uuid PRIMARY KEY, email text, raw_user_meta_data jsonb DEFAULT '{}'::jsonb); CREATE FUNCTION auth.role() RETURNS text LANGUAGE sql IMMUTABLE AS 'SELECT ''service_role''::text'; CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS 'SELECT NULL::uuid'");}executeMigration(connection,"20260927000001_auth_schema.sql");executeMigration(connection,"20260927000002_order_schema.sql");executeMigration(connection,"20260927000003_planning_schema.sql");executeMigration(connection,"20261003000005_order_service_owned_tables.sql");executeMigration(connection,"20261005000001_order_confirmation_lifecycle.sql");}registry.add("spring.datasource.url",postgres::getJdbcUrl);registry.add("spring.datasource.username",postgres::getUsername);registry.add("spring.datasource.password",postgres::getPassword);registry.add("spring.rabbitmq.host",()->"127.0.0.1");registry.add("spring.rabbitmq.password",()->"unused");}
 private static void executeMigration(Connection connection, String migration) throws IOException, SQLException {
  // Let PostgreSQL JDBC parse the complete script so semicolons inside dollar-quoted
  // function bodies are preserved. Spring ScriptUtils splits those bodies apart.
  String sql = Files.readString(Path.of("../../supabase/migrations", migration));
  try (Statement statement = connection.createStatement()) {
   statement.execute(sql);
  }
 }
 @Autowired MockMvc mvc;@Autowired ObjectMapper json;@Autowired JdbcTemplate jdbc;@Autowired EntityManager entityManager;@MockBean PlanningEventPublisher events;
 private UUID orderA;private UUID orderB;
 @BeforeEach void seed(){jdbc.update("INSERT INTO public.outlets(outlet_id,name,district,depot,parking_type) VALUES ('OUT-I','Integration Outlet','Colombo','D1','STANDARD') ON CONFLICT DO NOTHING");jdbc.update("INSERT INTO public.vehicles(vehicle_id,registration,type,weight_cap_kg,volume_cap_m3,temp_capability,depot,brand,is_active) VALUES ('VEH-I','INT-001','truck',4000,18,'CHILLED','D1','Fresh',true) ON CONFLICT DO NOTHING");jdbc.update("INSERT INTO public.vehicle_planning_state(vehicle_id,available,weekly_fuel_quota_l,weekly_fuel_used_l) VALUES ('VEH-I',true,100,20) ON CONFLICT(vehicle_id) DO UPDATE SET available=true");orderA=insertOrder(820,7.8);orderB=insertOrder(690,6.4);}
 @Test void rejectsRequestWithoutGatewayHeaders()throws Exception{mvc.perform(post("/api/planning/trips")).andExpect(status().isUnauthorized());}
 @Test void rejectsRequestWithoutGatewayVerifiedHeader()throws Exception{mvc.perform(post("/api/planning/trips").header("X-User-Id",TEST_USER_ID).header("X-User-Role","DISPATCHER").header("X-User-Email","dispatcher@example.test")).andExpect(status().isUnauthorized());}
 @Test void completeRestWorkflowPersistsAndReloads()throws Exception{String created=mvc.perform(post("/api/planning/trips").contentType("application/json").content("{\"planningDate\":\""+LocalDate.now()+"\",\"homeDepot\":\"D1\"}").with(gatewayIdentity())).andExpect(status().isCreated()).andReturn().getResponse().getContentAsString();UUID trip=UUID.fromString(json.readTree(created).get("tripId").asText());add(trip,orderA);add(trip,orderB);mvc.perform(put("/api/planning/trips/{id}/vehicle",trip).contentType("application/json").content("{\"vehicleId\":\"VEH-I\"}").with(gatewayIdentity())).andExpect(status().isOk());List<UUID> stopIdsBefore = jdbc.queryForList("SELECT trip_stop_id FROM public.trip_stops WHERE trip_id=? ORDER BY stop_sequence",UUID.class,trip);mvc.perform(put("/api/planning/trips/{id}/stops",trip).contentType("application/json").content(json.writeValueAsString(Map.of("orderIds",List.of(orderB,orderA)))).with(gatewayIdentity())).andExpect(status().isOk());assertThat(jdbc.queryForList("SELECT trip_stop_id FROM public.trip_stops WHERE trip_id=? ORDER BY stop_sequence",UUID.class,trip)).containsExactly(stopIdsBefore.get(1),stopIdsBefore.get(0));assertThat(jdbc.queryForList("SELECT stop_sequence FROM public.trip_stops WHERE trip_id=? ORDER BY stop_sequence",Integer.class,trip)).containsExactly(1,2);mvc.perform(post("/api/planning/trips/{id}/validate",trip).with(gatewayIdentity())).andExpect(status().isOk()).andExpect(jsonPath("$.feasible").value(true)).andExpect(jsonPath("$.totalWeight").value(1510.0));mvc.perform(post("/api/planning/trips/{id}/confirm",trip).with(gatewayIdentity())).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("CONFIRMED"));entityManager.clear();mvc.perform(get("/api/planning/trips/{id}",trip).with(gatewayIdentity())).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("CONFIRMED")).andExpect(jsonPath("$.vehicleId").value("VEH-I")).andExpect(jsonPath("$.stops[0].orderId").value(orderB.toString()));assertThat(jdbc.queryForObject("SELECT count(*) FROM public.allocations WHERE trip_id=? AND status::text='ALLOCATED'",Integer.class,trip)).isEqualTo(2);assertThat(jdbc.queryForObject("SELECT count(*) FROM public.trip_stops WHERE trip_id=?",Integer.class,trip)).isEqualTo(2);verify(events,times(1)).allocationCompleted(eq(trip),eq("VEH-I"),isNull(),eq(1),eq(LocalDate.now()),eq(TEST_USER_ID),anyList(),any());mvc.perform(post("/api/planning/trips/{id}/confirm",trip).with(gatewayIdentity())).andExpect(status().isOk());verifyNoMoreInteractions(events);mvc.perform(delete("/api/planning/trips/{id}/orders/{orderId}",trip,orderA).with(gatewayIdentity())).andExpect(status().isConflict());}
 private void add(UUID trip,UUID order)throws Exception{mvc.perform(post("/api/planning/trips/{id}/orders",trip).contentType("application/json").content("{\"orderId\":\""+order+"\"}").with(gatewayIdentity())).andExpect(status().isOk());}
 private static RequestPostProcessor gatewayIdentity(){return request->{request.addHeader("X-Gateway-Verified","true");request.addHeader("X-User-Id",TEST_USER_ID);request.addHeader("X-User-Role","DISPATCHER");request.addHeader("X-User-Email","dispatcher@example.test");return request;};}
 private UUID insertOrder(double weight,double volume){return jdbc.queryForObject("INSERT INTO public.orders(outlet_id,product_code,quantity,weight_kg,volume_m3,brand,temp_requirement,preferred_date,window_open,window_close,status) VALUES ('OUT-I','SKU',1,?,?, 'fresh','CHILLED',?, '06:00','12:00','CONFIRMED') RETURNING id",UUID.class,weight,volume,LocalDate.now());}
}
